usage:
const [day, setDay] = useState<Date>();

<Calendar selected={day} onSelect={setDay} />

// A span, which takes two taps to complete.
const [range, setRange] = useState<DateRange>();

<Calendar mode="range" selected={range} onSelect={setRange} />

examples.code:
{/* The default: drawn, dimmed, and not selectable. */}
<Calendar selected={day} onSelect={setDay} />

{/* Selectable from either side. */}
<Calendar selectOutsideDays selected={day} onSelect={setDay} />

{/* Not drawn at all — the cells are left blank. */}
<Calendar showOutsideDays={false} selected={day} onSelect={setDay} />
